using System.Collections;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "VortexBubbleEffect", menuName = "Data/Battle/Effects/Cellarius/VortexBubble Effect")]
public class VortexBubbleEffect : Effect
{
	[Header("Action Specifics")]
	[SerializeField]
	private int purifyCorruptAmountToTrigger;

	[SerializeField]
	private bool corruptedBubble;

	[SerializeField]
	private VortexBubbleCustomTag vortexBubbleCustomTag;

	public int PurifyCorruptAmountToTrigger => purifyCorruptAmountToTrigger;

	public bool CorruptedBubble => corruptedBubble;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetVortexBubbleBaseDescription(base.localizationManager.GetLocalizedX());
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return GetVortexBubbleBaseDescription(amount.ToString());
	}

	public string GetVortexBubbleBaseDescription(string effectAmount)
	{
		string localizedDescription = GetLocalizedDescription();
		string localizedThenDecreaseEffect = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedThenDecreaseEffect(this, 1);
		return Smart.Format(localizedDescription, purifyCorruptAmountToTrigger, base.localizationManager.GetLocalizedPurifyOrCorruptionWord(!corruptedBubble), effectAmount, localizedThenDecreaseEffect, Smart.Format(base.localizationManager.GetLocalizedString(vortexBubbleCustomTag.TagIDDescription), 1));
	}

	public bool CheckVortexBubbleEffect(int purifyCorruptAmount)
	{
		return purifyCorruptAmount >= purifyCorruptAmountToTrigger;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueOnBeforeAllActionsAction(VortexBubbleCoroutine(effectAmount, effectOwner));
		return effectAmount;
	}

	private IEnumerator VortexBubbleCoroutine(int purifyCorruptAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>().IsEffectActiveAndDecreaseEffect(this, 1, activateFeedback: false);
		yield return InvokeAlternatives.WaitForFrames(2);
		CorruptionStats component = effectOwner.GetComponent<CorruptionStats>();
		if (!corruptedBubble)
		{
			if (component.CurrentCorruption > 0f)
			{
				SpawnVFXAndPlaySFX(effectOwner);
				component.Purify(purifyCorruptAmount, null);
			}
		}
		else if (component is CorruptedAnimalCorruptionStats)
		{
			if (component.CurrentCorruption > 0f)
			{
				SpawnVFXAndPlaySFX(effectOwner);
				component.Corrupt(purifyCorruptAmount, null);
			}
		}
		else
		{
			SpawnVFXAndPlaySFX(effectOwner);
			component.Corrupt(purifyCorruptAmount, null);
		}
		yield return new WaitForSeconds(0.2f);
	}

	private void SpawnVFXAndPlaySFX(GameObject effectOwner)
	{
		if (IsVFXEnabled())
		{
			PlayEffectActivationSFX();
		}
		SpawnVFX(GetVFXOwnerPosition(effectOwner), 3f);
	}
}
